import os,glob,re
def load():
    d=os.path.normpath(os.environ['RLM_SESSION_DIR'])
    t=open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n'); G={}
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
        k,h,w=m[1],int(m[2]),int(m[3])
        rows=[r.split() for r in t[m.end():].split('\n')[:h]]
        if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
            G[k]=[[int(x) for x in r] for r in rows]
    return G
G=load(); print(sorted(G))
import json
def blocks(g):
    h,w=len(g),len(g[0]); seen=set(); out=[]
    for i in range(h):
        for j in range(w):
            if g[i][j] and (i,j) not in seen:
                st=[(i,j)]; seen.add((i,j)); cells=[]
                while st:
                    y,x=st.pop(); cells.append((y,x))
                    for dy,dx in((1,0),(-1,0),(0,1),(0,-1)):
                        ny,nx=y+dy,x+dx
                        if 0<=ny<h and 0<=nx<w and g[ny][nx] and (ny,nx) not in seen:
                            seen.add((ny,nx)); st.append((ny,nx))
                ys=[c[0] for c in cells]; xs=[c[1] for c in cells]
                out.append((min(ys),min(xs),max(ys),max(xs),len(cells)))
    return out
for k in ['Demo pair 1 input','Demo pair 1 output','Test input']:
    print(k)
    for b in blocks(G[k]): print(b)

import json
def transform(g):
    h,w=len(g),len(g[0]); seen=set(); blks=[]
    for i in range(h):
        for j in range(w):
            if g[i][j] and (i,j) not in seen:
                st=[(i,j)]; seen.add((i,j)); cells=[]
                while st:
                    y,x=st.pop(); cells.append((y,x))
                    for dy,dx in((1,0),(-1,0),(0,1),(0,-1)):
                        ny,nx=y+dy,x+dx
                        if 0<=ny<h and 0<=nx<w and g[ny][nx] and (ny,nx) not in seen:
                            seen.add((ny,nx)); st.append((ny,nx))
                blks.append(cells)
    smallest=min(blks,key=len)
    out=[row[:] for row in g]
    for y,x in smallest: out[y][x]=0
    return out
