for b in rem:
    y0,x0,y1,x1,_=b
    pat=[row[x0:x1+1] for row in inp[y0:y1+1]]
    ph,pw=len(pat),len(pat[0])
    hits=[]
    for b2 in keep:
        a0,c0,a1,c1,_=b2
        for i in range(a0,a1-ph+2):
            for j in range(c0,c1-pw+2):
                if [row[j:j+pw] for row in inp[i:i+ph]]==pat: hits.append((i,j))
    print('pattern',pat,'hits in kept:',hits)

def subpat_hits(inp,blocks):
    res={}
    for bi,b in enumerate(blocks):
        y0,x0,y1,x1,_=b
        pat=[row[x0:x1+1] for row in inp[y0:y1+1]]
        ph,pw=len(pat),len(pat[0]); hits=[]
        for bj,b2 in enumerate(blocks):
            if bj==bi: continue
            a0,c0,a1,c1,_=b2
            for i in range(a0,a1-ph+2):
                for j in range(c0,c1-pw+2):
                    if [row[j:j+pw] for row in inp[i:i+ph]]==pat: hits.append((bj,i,j))
        res[bi]=hits
    return res
bi=blocks(inp); r=subpat_hits(inp,bi)
print('demo:',{k:v for k,v in r.items()})
